    routes = [rt for rt in routes if rt]

    seen = set()
    cleaned = []
    for rt in routes:
        nr = []
        for c in rt:
            if c not in seen and c != depot:
                nr.append(c)
                seen.add(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    missing = [c for c in customers if c not in seen]
    if missing:
        # Insert missing customers into the cheapest feasible positions; create new routes if needed.
        for c in sorted(missing, key=lambda x: (demand_of(x), dist(depot, x), x)):
            best = None
            best_cost = None
            dc = demand_of(c)
            for r_idx, rt in enumerate(routes):
                if route_load(rt) + dc > capacity:
                    continue
                for pos in range(len(rt) + 1):
                    cand = rt[:pos] + [c] + rt[pos:]
                    cost = route_length(cand) - route_length(rt)
                    if best is None or cost < best_cost - 1e-12 or (abs(cost - best_cost) <= 1e-12 and (r_idx, pos) < (best[0], best[1])):
                        best = (r_idx, pos, cand)
                        best_cost = cost
            if best is not None:
                r_idx, pos, cand = best
                routes[r_idx] = cand
            else:
                routes.append([c])

    # Final deterministic ordering of routes
    routes.sort(key=lambda rt: (route_length(rt), len(rt), rt[0] if rt else -1))
    return routes
